-- pharm-001 (questions-bank\pharmacology\pharm-001.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Toxicities and Adverse Effects',
    'Acetaminophen toxicity',
    'A 22-year-old woman is brought to the emergency department 6 hours after ingesting 20 tablets of acetaminophen 500 mg in a suicide attempt. She has a history of chronic alcohol use disorder. Laboratory studies show elevated AST and ALT.',
    'Which of the following is the most appropriate antidote to prevent hepatic injury?',
    '[{"id":"A","text":"N-Acetylcysteine"},{"id":"B","text":"Deferoxamine"},{"id":"C","text":"Fomepizole"},{"id":"D","text":"Naloxone"},{"id":"E","text":"Physostigmine"}]'::jsonb,
    'A',
    'N-Acetylcysteine replenishes hepatic glutathione and provides sulfhydryl groups that conjugate the toxic metabolite NAPQI. NAPQI accumulates when acetaminophen is oxidized by CYP2E1 and glutathione stores are depleted; chronic alcohol use induces CYP2E1 and increases NAPQI formation, making hepatotoxicity more likely.',
    '{"B":"Deferoxamine is an iron chelator used for iron poisoning.","C":"Fomepizole inhibits alcohol dehydrogenase and is used for methanol or ethylene glycol poisoning.","D":"Naloxone is an opioid receptor antagonist used for opioid overdose.","E":"Physostigmine is a cholinesterase inhibitor used for anticholinergic toxicity."}'::jsonb,
    'easy'
where not exists (
  select 1 from public.questions
  where vignette = 'A 22-year-old woman is brought to the emergency department 6 hours after ingesting 20 tablets of acetaminophen 500 mg in a suicide attempt. She has a history of chronic alcohol use disorder. Laboratory studies show elevated AST and ALT.' and question = 'Which of the following is the most appropriate antidote to prevent hepatic injury?'
);

-- pharm-002 (questions-bank\pharmacology\pharm-002.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Autonomic Drugs',
    'Cholinesterase inhibitors and organophosphate poisoning',
    'A farmworker is found confused, sweating profusely, and in respiratory distress after spraying crops without protective equipment. Examination shows miosis, bradycardia, bronchorrhea, and muscle fasciculations.',
    'Which of the following is the most appropriate initial pharmacologic treatment?',
    '[{"id":"A","text":"Atropine followed by pralidoxime"},{"id":"B","text":"Pralidoxime followed by atropine"},{"id":"C","text":"Physostigmine"},{"id":"D","text":"Naloxone"},{"id":"E","text":"Succinylcholine"}]'::jsonb,
    'A',
    'Organophosphates irreversibly inhibit acetylcholinesterase, producing cholinergic excess with miosis, bradycardia, bronchorrhea, and fasciculations. Atropine is given first to block muscarinic effects such as bronchorrhea and bradycardia, and pralidoxime is then used to reactivate acetylcholinesterase before the enzyme ages.',
    '{"B":"The order is reversed: atropine must come first to dry secretions and support the airway, and pralidoxime works only while the enzyme can still be reactivated.","C":"Physostigmine inhibits acetylcholinesterase and would worsen cholinergic toxicity.","D":"Naloxone is an opioid antagonist and has no role in organophosphate poisoning.","E":"Succinylcholine is metabolized by pseudocholinesterase, which is inhibited in organophosphate poisoning, so its effect would be dangerously prolonged."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A farmworker is found confused, sweating profusely, and in respiratory distress after spraying crops without protective equipment. Examination shows miosis, bradycardia, bronchorrhea, and muscle fasciculations.' and question = 'Which of the following is the most appropriate initial pharmacologic treatment?'
);

-- pharm-003 (questions-bank\pharmacology\pharm-003.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Autonomic Drugs',
    'Muscarinic antagonists and anticholinergic toxicity',
    'A 19-year-old man is brought in after eating berries from a plant he found while hiking. He is agitated and incoherent. Examination shows dry flushed skin, dilated pupils, urinary retention, and a temperature of 39.2 degrees Celsius.',
    'Which of the following is the most appropriate antidote?',
    '[{"id":"A","text":"Physostigmine"},{"id":"B","text":"Neostigmine"},{"id":"C","text":"Atropine"},{"id":"D","text":"Pralidoxime"},{"id":"E","text":"Flumazenil"}]'::jsonb,
    'A',
    'This is the anticholinergic toxidrome (hot, dry, mad, blind, full). Physostigmine is a tertiary amine that crosses the blood-brain barrier and reversibly inhibits acetylcholinesterase centrally and peripherally. Supportive cooling is also required; physostigmine is avoided when tricyclic antidepressant co-ingestion is suspected.',
    '{"B":"Neostigmine is a quaternary amine that does not cross the blood-brain barrier, so it cannot reverse central anticholinergic effects.","C":"Atropine is itself a muscarinic antagonist and would worsen the toxidrome.","D":"Pralidoxime is used for organophosphate poisoning to reactivate acetylcholinesterase.","E":"Flumazenil is a benzodiazepine antagonist and has no role in anticholinergic toxicity."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 19-year-old man is brought in after eating berries from a plant he found while hiking. He is agitated and incoherent. Examination shows dry flushed skin, dilated pupils, urinary retention, and a temperature of 39.2 degrees Celsius.' and question = 'Which of the following is the most appropriate antidote?'
);

-- pharm-004 (questions-bank\pharmacology\pharm-004.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Toxicities and Adverse Effects',
    'Methanol and ethylene glycol toxicity',
    'A 45-year-old man presents 12 hours after drinking homemade alcohol with blurred vision described as a snowfield and worsening confusion. Laboratory studies show a high anion gap metabolic acidosis and an elevated osmolar gap.',
    'Which of the following is the most appropriate initial treatment?',
    '[{"id":"A","text":"Fomepizole"},{"id":"B","text":"N-Acetylcysteine"},{"id":"C","text":"Naloxone"},{"id":"D","text":"Hydroxocobalamin"},{"id":"E","text":"Disulfiram"}]'::jsonb,
    'A',
    'Methanol is oxidized by alcohol dehydrogenase to formaldehyde and then formic acid, which damages the retina and causes severe metabolic acidosis. Fomepizole inhibits alcohol dehydrogenase and prevents formation of these toxic metabolites; severe cases also require hemodialysis.',
    '{"B":"N-Acetylcysteine is the antidote for acetaminophen overdose.","C":"Naloxone is an opioid antagonist.","D":"Hydroxocobalamin is used for cyanide poisoning.","E":"Disulfiram inhibits acetaldehyde dehydrogenase and is used as aversion therapy for alcohol use disorder; it does not treat methanol poisoning."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 45-year-old man presents 12 hours after drinking homemade alcohol with blurred vision described as a snowfield and worsening confusion. Laboratory studies show a high anion gap metabolic acidosis and an elevated osmolar gap.' and question = 'Which of the following is the most appropriate initial treatment?'
);

-- pharm-005 (questions-bank\pharmacology\pharm-005.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Toxicities and Adverse Effects',
    'Salicylate toxicity',
    'A 30-year-old woman with rheumatoid arthritis is brought in after ingesting a large quantity of aspirin. She is tachypneic and confused. Arterial blood gas shows pH 7.48 and PaCO2 22 mm Hg, and serum chemistry shows bicarbonate 16 mEq/L with an elevated anion gap.',
    'Which of the following is the most appropriate specific treatment?',
    '[{"id":"A","text":"Sodium bicarbonate"},{"id":"B","text":"Acetazolamide"},{"id":"C","text":"N-Acetylcysteine"},{"id":"D","text":"Fomepizole"},{"id":"E","text":"Vitamin K"}]'::jsonb,
    'A',
    'Salicylates directly stimulate the respiratory center, producing respiratory alkalosis early, and later uncouple oxidative phosphorylation, generating organic acids and a high anion gap metabolic acidosis. Sodium bicarbonate alkalinizes serum and urine, increasing the ionized fraction of salicylate and its renal excretion; hemodialysis is used for severe toxicity.',
    '{"B":"Acetazolamide alkalinizes the urine but worsens systemic metabolic acidosis and is not used in salicylate poisoning.","C":"N-Acetylcysteine is the antidote for acetaminophen overdose.","D":"Fomepizole is used for methanol or ethylene glycol poisoning.","E":"Vitamin K reverses warfarin, not salicylates."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 30-year-old woman with rheumatoid arthritis is brought in after ingesting a large quantity of aspirin. She is tachypneic and confused. Arterial blood gas shows pH 7.48 and PaCO2 22 mm Hg, and serum chemistry shows bicarbonate 16 mEq/L with an elevated anion gap.' and question = 'Which of the following is the most appropriate specific treatment?'
);

-- pharm-006 (questions-bank\pharmacology\pharm-006.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Toxicities and Adverse Effects',
    'Tricyclic antidepressant toxicity',
    'A 25-year-old woman presents with confusion, dry mouth, and blurred vision after ingesting a bottle of amitriptyline. ECG shows a QRS duration of 130 ms and runs of ventricular tachycardia.',
    'Which of the following is the most appropriate initial treatment for this patient''s cardiac toxicity?',
    '[{"id":"A","text":"Sodium bicarbonate"},{"id":"B","text":"Physostigmine"},{"id":"C","text":"Flumazenil"},{"id":"D","text":"Pralidoxime"},{"id":"E","text":"Glucagon"}]'::jsonb,
    'A',
    'Tricyclic antidepressants block cardiac sodium channels, widening the QRS and predisposing to ventricular arrhythmias. Intravenous sodium bicarbonate provides a sodium load and alkalinizes the serum, stabilizing the cardiac membrane; physostigmine is contraindicated because it can worsen conduction disturbances and seizures.',
    '{"B":"Physostigmine is contraindicated in tricyclic antidepressant overdose because it can precipitate seizures and cardiac conduction abnormalities.","C":"Flumazenil reverses benzodiazepines and may precipitate seizures in mixed overdose.","D":"Pralidoxime is used for organophosphate poisoning.","E":"Glucagon is used for beta-blocker overdose."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 25-year-old woman presents with confusion, dry mouth, and blurred vision after ingesting a bottle of amitriptyline. ECG shows a QRS duration of 130 ms and runs of ventricular tachycardia.' and question = 'Which of the following is the most appropriate initial treatment for this patient''s cardiac toxicity?'
);

