  select 1 from public.questions
  where vignette = 'A 58-year-old man taking simvastatin for hyperlipidemia is prescribed clarithromycin for sinusitis. Two weeks later he presents with diffuse muscle pain and dark urine. Creatine kinase is 12,000 U/L and creatinine is elevated.' and question = 'Which of the following best explains this patient''s presentation?'
);

