    '[{"id":"A","text":"Glucagon"},{"id":"B","text":"Naloxone"},{"id":"C","text":"Flumazenil"},{"id":"D","text":"Digoxin-specific antibody fragments"},{"id":"E","text":"Intravenous calcium chloride"}]'::jsonb,
    'A',
    'Glucagon activates adenylate cyclase through a G-protein-coupled receptor that bypasses the blocked beta-adrenergic receptor, increasing intracellular cAMP and improving heart rate and contractility. High-dose insulin with euglycemia and transvenous pacing are additional options.',
    '{"B":"Naloxone is an opioid antagonist.","C":"Flumazenil is a benzodiazepine antagonist.","D":"Digoxin-specific antibody fragments treat digoxin toxicity.","E":"Calcium chloride is used for calcium channel blocker overdose, not beta-blocker overdose."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 40-year-old man presents with a heart rate of 38/min, blood pressure of 76/50 mm Hg, and hypoglycemia after ingesting a large number of metoprolol tablets.' and question = 'In addition to intravenous fluids and atropine, which of the following is the most appropriate treatment?'
);

