    '{"B":"Cyanocobalamin treats vitamin B12 deficiency, which can cause neuropathy but is not the mechanism here.","C":"Thiamine deficiency causes beriberi and Wernicke encephalopathy.","D":"Folic acid deficiency causes megaloblastic anemia, not this neuropathy.","E":"Ascorbic acid is vitamin C and is unrelated to isoniazid neuropathy."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 34-year-old man with active tuberculosis started on isoniazid, rifampin, pyrazinamide, and ethambutol 2 months ago presents with numbness and tingling of both feet.' and question = 'Which of the following is the most appropriate treatment to prevent progression of this complication?'
);

-- pharm-020 (questions-bank\pharmacology\pharm-020.json)
insert into public.questions (subject, major_topic, subtopic, vignette, question, options, correct_answer, explanation_correct, explanation_incorrect, difficulty)
select
    'Pharmacology',
    'Pharmacokinetics and Pharmacodynamics',
    'Zero-order elimination',
    'A 24-year-old man with epilepsy has been taking phenytoin 300 mg/day with a serum concentration of 12 micrograms/mL. After the dose is increased to 400 mg/day, the concentration rises to 28 micrograms/mL and he develops nystagmus and ataxia.',
    'Which of the following best explains this finding?',
    '[{"id":"A","text":"Saturation of hepatic metabolism (zero-order kinetics)"},{"id":"B","text":"Increased volume of distribution"},{"id":"C","text":"Decreased plasma protein binding"},{"id":"D","text":"Impaired renal clearance"},{"id":"E","text":"Enzyme induction"}]'::jsonb,
    'A',
    'Phenytoin, like ethanol and high-dose aspirin, follows zero-order (saturable) elimination: once hepatic enzymes are saturated, a constant amount of drug is eliminated per unit time, so a small dose increase can produce a disproportionately large rise in serum concentration and toxicity.',
    '{"B":"A change in volume of distribution would not produce this disproportionate rise at steady state.","C":"Decreased protein binding would lower total drug concentration rather than raising it sharply.","D":"Phenytoin is metabolized hepatically, not cleared unchanged by the kidney.","E":"Enzyme induction would lower serum concentrations rather than raise them."}'::jsonb,
    'medium'
where not exists (
  select 1 from public.questions
  where vignette = 'A 24-year-old man with epilepsy has been taking phenytoin 300 mg/day with a serum concentration of 12 micrograms/mL. After the dose is increased to 400 mg/day, the concentration rises to 28 micrograms/mL and he develops nystagmus and ataxia.' and question = 'Which of the following best explains this finding?'
);
commit;
